/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type PackageChange = "major" | "minor" | "patch" | "added" | "removed"

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const SEMVER = /^v?(\d+)\.(\d+)\.(\d+)/

/** Which part of the version moved, read from two semver strings. */
export function semverChange(from?: string, to?: string): PackageChange | undefined {
  if (!from && to) return "added"
  if (from && !to) return "removed"
  const a = SEMVER.exec(from ?? "")
  const b = SEMVER.exec(to ?? "")
  if (!a || !b) return undefined
  if (a[1] !== b[1]) return "major"
  if (a[2] !== b[2]) return "minor"
  return "patch"
}

export interface PackageDependency {
  name: string
  version?: string
  /** For an update, the version it moved from. */
  from?: string
  change: "added" | "removed" | "updated"
}

export type PackageInfoState = "installing" | "installed" | "failed"

export interface PackageInfoLabels {
  installing: string
  failed: string
  retry: string
  dependencies: (n: number) => string
  copy: string
  open: string
  changes: Record<PackageChange, string>
}

export interface PackageInfoProps extends Omit<React.ComponentProps<"div">, "children"> {
  name: string
  /** The version now. Leave out for a removed package. */
  version?: string
  /** The version before, for an upgrade or downgrade. */
  previousVersion?: string
  /** Read from the two versions when left out. */
  change?: PackageChange
  description?: React.ReactNode
  dependencies?: PackageDependency[]
  license?: string
  /** Install size in bytes, gzip. */
  size?: number
  href?: string
  /** The command shown and copied, for example `pnpm add zod@4.1.0`. */
  command?: string
  state?: PackageInfoState
  error?: React.ReactNode
  onRetry?: () => void
  labels?: Partial<PackageInfoLabels>
}

const defaultLabels: PackageInfoLabels = {
  installing: "Installing",
  failed: "Install failed",
  retry: "Retry",
  dependencies: (n) => (n === 1 ? "1 dependency changed" : `${n} dependencies changed`),
  copy: "Copy install command",
  open: "Open on the registry",
  changes: {
    major: "Major, may break",
    minor: "Minor",
    patch: "Patch",
    added: "Added",
    removed: "Removed",
  },
}

/** The kit's one spinner. 0.8 s per turn, slowed to 1.2 s under reduced motion. */
function Spinner({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      data-slot="spinner"
      className={cn("chatcn-spin size-3.5 shrink-0", className)}
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeOpacity="0.2" strokeWidth="1.5" />
      <path
        d="M8 1.75A6.25 6.25 0 0 1 14.25 8"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

