/** Copy swaps to a check with a 150 ms blur crossfade, holds for 1.5 s and announces itself. */
function CopyButton({
  value,
  label = "Copy",
  onCopy,
  onClick,
  children,
  size = "icon-sm",
  className,
  ...props
}: CopyButtonProps) {
  // A counter, not a flag: copying again while the check shows restarts the 1.5 s hold.
  const [copies, setCopies] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copies) return
    setCopied(true)
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copies])

  // Reduced motion keeps the crossfade and drops the scale and blur.
  const layer = cn(
    "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
    "motion-reduce:scale-100 motion-reduce:blur-none motion-reduce:transition-opacity",
  )
  return (
    <Button
      {...props}
      size={size}
      aria-label={children ? undefined : copied ? "Copied" : label}
      onClick={(event) => {
        // Compose with handlers injected by wrappers such as Tooltip instead of replacing them.
        onClick?.(event)
        if (event.defaultPrevented) return
        const text = typeof value === "function" ? value() : value
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopies((n) => n + 1)
            onCopy?.(text)
          })
          // Clipboard access can be denied (insecure context, permissions). Stay quiet and unchanged.
          .catch(() => {})
      }}
      className={cn("relative", className)}
    >
      {children ? (
        <>
          <span className="relative grid size-3.5 place-items-center">
            <CopyIcon
              className={cn(
                layer,
                copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
              )}
            />
            <CheckIcon
              className={cn(
                layer,
                copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
              )}
            />
          </span>
          {children}
        </>
      ) : null}
      {children ? null : (
        <>
          <CopyIcon
            className={cn(
              layer,
              copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
            )}
          />
          <CheckIcon
            className={cn(
              layer,
              copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
            )}
          />
        </>
      )}
      <span aria-live="polite" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </Button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * PackageInfo
 * -----------------------------------------------------------------------------------------------*/

/**
 * A package an agent added, upgraded or removed. The version change reads at a glance, from and
 * to, with what kind of change it is in words and color: a major bump says it may break, which is
 * the one thing a reviewer needs to notice. The dependencies it pulled in or dropped sit behind a
 * count, each marked with a plus or minus. While installing it says so; if it fails, the error
 * says why and Retry is right there.
 */
export function PackageInfo({
  name,
  version,
  previousVersion,
  change: changeProp,
  description,
  dependencies = [],
  license,
  size,
  href,
  command,
  state = "installed",
  error,
  onRetry,
  labels: labelsProp,
  className,
  ...props
}: PackageInfoProps) {
  const labels = { ...defaultLabels, ...labelsProp }
  const change = changeProp ?? semverChange(previousVersion, version)
  const [open, setOpen] = React.useState(false)
  const listId = React.useId()

  return (
    <div
      data-slot="package-info"
      data-state={state}
      data-change={change}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) w-full overflow-hidden",
        className,
      )}
      {...props}
    >
      <div className="flex items-start gap-3 p-3.5">
        <span
          aria-hidden="true"
          className="bg-(color:--chatcn-fill) text-(color:--chatcn-fg-muted) rounded-(--chatcn-radius-md) grid size-8 shrink-0 place-items-center [&_svg]:size-4"
        >
          {state === "installing" ? <Spinner className="size-4" /> : <PackageIcon />}
        </span>
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <div className="flex min-w-0 flex-wrap items-center gap-x-2.5 gap-y-1">
            <span className="min-w-0 truncate font-mono font-medium">{name}</span>
            {previousVersion || version ? (
              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) inline-flex items-center gap-1.5 font-mono tabular-nums">
                {previousVersion ? (
                  <span className={cn(version && "line-through decoration-1 opacity-70")}>
                    {previousVersion}
                  </span>
                ) : null}
                {previousVersion && version ? (
                  <ArrowRightIcon aria-hidden="true" className="size-3 shrink-0 rtl:-scale-x-100" />
                ) : null}
                {version ? <span className="text-(color:--chatcn-fg)">{version}</span> : null}
              </span>
            ) : null}
            {change && state !== "failed" ? (
              <span
                className={cn(
                  "text-[0.75rem]/[1rem] rounded-(--chatcn-radius-sm) px-1.5 py-px font-medium whitespace-nowrap",
                  changeTone[change],
                )}
              >
                {labels.changes[change]}
              </span>
            ) : null}
          </div>
          {state === "installing" ? (
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">{labels.installing}</span>
          ) : description ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{description}</p>
          ) : null}
        </div>
        {href ? (
          <a
            href={href}
            target="_blank"
            rel="noreferrer"
            aria-label={`${labels.open}: ${name}`}
            className="chatcn-focus rounded-(--chatcn-radius-md) text-(color:--chatcn-fg-subtle) [@media(hover:hover)]:hover:bg-(color:--chatcn-fill-hover) [@media(hover:hover)]:hover:text-(color:--chatcn-fg) grid size-8 shrink-0 place-items-center pointer-coarse:size-11"
          >
            <ExternalLinkIcon aria-hidden="true" className="size-4" />
          </a>
        ) : null}
      </div>

      {state === "failed" ? (
        <div className="border-(color:--chatcn-border) flex items-start gap-2.5 border-t px-3.5 py-3">
          <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red) mt-0.5 size-4 shrink-0" />
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-red) font-medium">{labels.failed}</span>
            {error ? (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{error}</p>
            ) : null}
          </div>
          {onRetry ? (
            <Button size="sm" variant="outline" onClick={onRetry} className="shrink-0">
              <RotateCcwIcon />
              {labels.retry}
            </Button>
          ) : null}
        </div>
      ) : null}

      {dependencies.length > 0 && state !== "failed" ? (
        <div className="border-(color:--chatcn-border) border-t">
          <button
            type="button"
            aria-expanded={open}
            aria-controls={listId}
            onClick={() => setOpen((o) => !o)}
            className="chatcn-focus text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) [@media(hover:hover)]:hover:text-(color:--chatcn-fg) flex h-9 w-full items-center gap-2 px-3.5 text-start"
          >
            <ChevronDownIcon
              aria-hidden="true"
              className={cn(
                "size-3.5 shrink-0 transition-transform duration-150",
                !open && "-rotate-90 rtl:rotate-90",
              )}
            />
            {labels.dependencies(dependencies.length)}
          </button>
          {open ? (
            <ul
              id={listId}
              className="text-[0.8125rem]/[1.25rem] flex flex-col gap-1 px-3.5 ps-9 pb-3 font-mono motion-safe:animate-[chatcn-enter_180ms_var(--chatcn-ease-out)]"
            >
              {dependencies.map((d) => (
                <li key={d.name} className="flex min-w-0 items-baseline gap-2">
                  <span
                    aria-hidden="true"
                    className={cn(
                      "w-3 shrink-0 text-center",
                      d.change === "added"
                        ? "text-(color:--chatcn-green)"
                        : d.change === "removed"
                          ? "text-(color:--chatcn-red)"
                          : "text-(color:--chatcn-fg-subtle)",
                    )}
                  >
                    {d.change === "added" ? "+" : d.change === "removed" ? "-" : "~"}
                  </span>
                  <span className="sr-only">{d.change}</span>
                  <span className="text-(color:--chatcn-fg) min-w-0 truncate">{d.name}</span>
                  <span className="text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
                    {d.from ? `${d.from} to ` : ""}
                    {d.version}
                  </span>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}

      {command || license || size !== undefined ? (
        <div className="border-(color:--chatcn-border) bg-(color:--chatcn-bg-subtle) flex min-h-10 items-center gap-3 border-t ps-3.5 pe-1.5">
          {command ? (
            <code className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) min-w-0 flex-1 truncate font-mono">
              {command}
            </code>
          ) : (
            <span className="flex-1" />
          )}
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-2 tabular-nums">
            {license ? <span>{license}</span> : null}
            {license && size !== undefined ? <span aria-hidden="true">·</span> : null}
            {size !== undefined ? <span>{formatSize(size)} gzip</span> : null}
          </span>
          {command ? <CopyButton value={command} label={labels.copy} /> : null}
        </div>
      ) : null}
    </div>
  )
}

